local SHADOWLANDS_MAP_IDS = {
    ["Bastion"] = 1533, ["Maldraxxus"] = 1536, ["Ardenweald"] = 1565,
    ["Revendreth"] = 1525, ["The Maw"] = 1543, ["Korthia"] = 1961,
    ["Zereth Mortis"] = 1970,
}

local function CopySpot(spot)
    local copy = {}
    for key, value in pairs(spot) do
        copy[key] = value
    end
    copy.mapID = copy.mapID or SHADOWLANDS_MAP_IDS[copy.mapName]
    copy.isRoute = false
    return copy
end

-- Baits can be fished as well as purchased. Reuse the existing, sourced
-- matching-fish water markers; no new bait-node geometry is inferred.
local BAIT_FISH = {
    [173038] = 173032, [173039] = 173033, [173040] = 173034,
    [173041] = 173035, [173042] = 173036, [173043] = 173037,
    [187712] = 187702,
}
for baitID, fishID in pairs(BAIT_FISH) do
    local bait, fish = Items[baitID], Items[fishID]
    for _, fishSpot in ipairs(fish and fish.spots or {}) do
        local spot = CopySpot(fishSpot)
        spot.id = fishSpot.id .. "-bait-" .. baitID
        spot.tips = bait.tips
        spot.sourceUrls = bait.sourceUrls
        spot.routeType = "fishing-chance-source"
        spot.dropDifficulty = "Chance bait catch from suitable water; no guaranteed bait yield."
        bait.spots[#bait.spots + 1] = spot
    end
end

-- Copy each non-ore/herb spot before marking it as a pin. Stone records can
-- share legacy spot tables with ore records; those ore flags stay untouched.
for _, item in pairs(Items) do
    if item.expansion == "shadowlands" and item.category ~= "Herb" and item.category ~= "Ore" then
        item.isRoute = false
        local spots = {}
        for _, spot in ipairs(item.spots or {}) do
            spots[#spots + 1] = CopySpot(spot)
        end
        item.spots = spots
    end
end
